#!/usr/bin/env python3
"""提取 Claude Code 会话记录 (jsonl) 中的对话内容，整理为 JSON。"""

import json
import glob
import os
import sys

SRC_DIR = "/home/mi/.claude/projects/-home-mi-sp-vela-apps-wake-demo"
OUT_FILE = "/home/mi/sp_vela/apps/wake_demo/ai_conversations.json"


def extract_text(content):
    """从 message.content 中提取可读文本。content 可能是 str 或 block 列表。"""
    if isinstance(content, str):
        return content
    parts = []
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                continue
            btype = block.get("type")
            if btype == "text":
                parts.append(block.get("text", ""))
            elif btype == "tool_use":
                name = block.get("name", "?")
                parts.append(f"[调用工具: {name}]")
            elif btype == "tool_result":
                # 工具结果只保留摘要，避免体积过大
                c = block.get("content")
                text = extract_text(c) if c else ""
                text = text.strip()
                if len(text) > 500:
                    text = text[:500] + "...(截断)"
                if text:
                    parts.append(f"[工具结果] {text}")
            elif btype == "thinking":
                pass  # 跳过思考过程
    return "\n".join(p for p in parts if p)


def parse_session(path):
    session_id = os.path.basename(path).replace(".jsonl", "")
    messages = []
    cwd = None
    git_branch = None
    start_time = None
    end_time = None

    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue

            rtype = rec.get("type")
            if rtype not in ("user", "assistant"):
                continue
            if rec.get("isSidechain"):
                continue  # 跳过子代理侧链消息

            msg = rec.get("message") or {}
            role = msg.get("role", rtype)
            text = extract_text(msg.get("content"))
            if not text.strip():
                continue

            ts = rec.get("timestamp")
            if ts:
                if start_time is None:
                    start_time = ts
                end_time = ts
            if cwd is None:
                cwd = rec.get("cwd")
            if git_branch is None:
                git_branch = rec.get("gitBranch")

            messages.append({
                "role": role,
                "timestamp": ts,
                "content": text,
            })

    return {
        "session_id": session_id,
        "cwd": cwd,
        "git_branch": git_branch,
        "start_time": start_time,
        "end_time": end_time,
        "message_count": len(messages),
        "messages": messages,
    }


def main():
    src_dir = sys.argv[1] if len(sys.argv) > 1 else SRC_DIR
    out_file = sys.argv[2] if len(sys.argv) > 2 else OUT_FILE

    files = sorted(glob.glob(os.path.join(src_dir, "*.jsonl")))
    if not files:
        print(f"未在 {src_dir} 找到会话记录")
        sys.exit(1)

    sessions = []
    for path in files:
        s = parse_session(path)
        sessions.append(s)
        print(f"会话 {s['session_id']}: {s['message_count']} 条消息 "
              f"({s['start_time']} ~ {s['end_time']})")

    sessions.sort(key=lambda s: s["start_time"] or "")

    result = {
        "source_dir": src_dir,
        "session_count": len(sessions),
        "total_messages": sum(s["message_count"] for s in sessions),
        "sessions": sessions,
    }

    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)

    print(f"\n已保存到 {out_file} ({os.path.getsize(out_file)} 字节)")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""提取 Claude Code 会话记录 (jsonl) 中的对话内容，整理为 JSON。

每条消息保留完整的结构化 blocks：
- text:        可读文本
- tool_use:    工具调用，含完整输入参数 (input)
- tool_result: 工具返回，含完整输出内容 (content)，不截断
"""

import json
import glob
import os
import sys

SRC_DIR = "/home/mi/.claude/projects/-home-mi-sp-vela-apps-wake-demo"
OUT_FILE = "/home/mi/sp_vela/apps/wake_demo/ai_conversations.json"


def extract_blocks(content):
    """把 message.content 解析为结构化 block 列表。content 可能是 str 或 block 列表。"""
    if isinstance(content, str):
        return [{"type": "text", "text": content}] if content else []

    blocks = []
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                continue
            btype = block.get("type")
            if btype == "text":
                blocks.append({"type": "text", "text": block.get("text", "")})
            elif btype == "tool_use":
                blocks.append({
                    "type": "tool_use",
                    "id": block.get("id"),
                    "name": block.get("name", "?"),
                    "input": block.get("input"),  # 完整输入参数
                })
            elif btype == "tool_result":
                c = block.get("content")
                # content 可能是 str 或嵌套 block 列表，统一递归提取
                if isinstance(c, list):
                    sub = extract_blocks(c)
                    text = "\n".join(b.get("text", "") for b in sub if b["type"] == "text")
                else:
                    text = c if isinstance(c, str) else ""
                blocks.append({
                    "type": "tool_result",
                    "tool_use_id": block.get("tool_use_id"),
                    "is_error": block.get("is_error", False),
                    "content": text,  # 完整输出，不截断
                })
            elif btype == "thinking":
                pass  # 跳过思考过程
    return blocks


def flatten_text(blocks):
    """生成一份可读的内容摘要，方便快速浏览。"""
    parts = []
    for b in blocks:
        if b["type"] == "text":
            parts.append(b["text"])
        elif b["type"] == "tool_use":
            inp = json.dumps(b.get("input"), ensure_ascii=False)
            if len(inp) > 200:
                inp = inp[:200] + "..."
            parts.append(f"[调用工具: {b['name']}] {inp}")
        elif b["type"] == "tool_result":
            text = (b.get("content") or "").strip()
            if len(text) > 200:
                text = text[:200] + "...(完整内容见 blocks)"
            tag = "[工具结果-错误]" if b.get("is_error") else "[工具结果]"
            if text:
                parts.append(f"{tag} {text}")
    return "\n".join(p for p in parts if p)


def parse_session(path):
    session_id = os.path.basename(path).replace(".jsonl", "")
    messages = []
    cwd = None
    git_branch = None
    start_time = None
    end_time = None

    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue

            rtype = rec.get("type")
            if rtype not in ("user", "assistant"):
                continue
            if rec.get("isSidechain"):
                continue  # 跳过子代理侧链消息

            msg = rec.get("message") or {}
            role = msg.get("role", rtype)
            blocks = extract_blocks(msg.get("content"))
            if not blocks:
                continue

            ts = rec.get("timestamp")
            if ts:
                if start_time is None:
                    start_time = ts
                end_time = ts
            if cwd is None:
                cwd = rec.get("cwd")
            if git_branch is None:
                git_branch = rec.get("gitBranch")

            messages.append({
                "role": role,
                "timestamp": ts,
                "content": flatten_text(blocks),  # 可读摘要
                "blocks": blocks,                 # 完整结构化内容（含工具输入/输出）
            })

    return {
        "session_id": session_id,
        "cwd": cwd,
        "git_branch": git_branch,
        "start_time": start_time,
        "end_time": end_time,
        "message_count": len(messages),
        "messages": messages,
    }


def main():
    # 用法: extract_conversations.py <输出文件> <会话目录> [更多会话目录...]
    out_file = sys.argv[1] if len(sys.argv) > 1 else OUT_FILE
    src_dirs = sys.argv[2:] if len(sys.argv) > 2 else [SRC_DIR]

    projects = []
    for src_dir in src_dirs:
        files = sorted(glob.glob(os.path.join(src_dir, "*.jsonl")))
        if not files:
            print(f"未在 {src_dir} 找到会话记录，跳过")
            continue

        sessions = []
        for path in files:
            s = parse_session(path)
            sessions.append(s)
            print(f"会话 {s['session_id']}: {s['message_count']} 条消息 "
                  f"({s['start_time']} ~ {s['end_time']})")

        sessions.sort(key=lambda s: s["start_time"] or "")
        projects.append({
            "project_dir": src_dir,
            "session_count": len(sessions),
            "total_messages": sum(s["message_count"] for s in sessions),
            "sessions": sessions,
        })

    result = {
        "project_count": len(projects),
        "session_count": sum(p["session_count"] for p in projects),
        "total_messages": sum(p["total_messages"] for p in projects),
        "projects": projects,
    }

    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)

    print(f"\n已保存到 {out_file} ({os.path.getsize(out_file)} 字节)")


if __name__ == "__main__":
    main()

